/* A short guided flow, keeping the original model and source details. */
window.Journey=(()=>{
 const $=id=>document.getElementById(id);let step=0;
 const main=document.querySelector('main'),hero=document.querySelector('.intro');
 document.title='Shift Out of Luck · NYC';document.querySelector('header a').textContent='SHIFT OUT OF LUCK / NYC';
 hero.innerHTML='<p class="eyebrow">PUBLIC SERVICES. PERSONAL SCHEDULING PROBLEMS.</p><h1>Can the city fit<br><em>into your day?</em></h1>';
 const nav=document.createElement('nav');nav.className='journey-nav';nav.setAttribute('aria-label','Your plan');
 const labels=['Your places','Getting around','Your work','Your life','Your errand','Your options'];
 nav.innerHTML=labels.map((l,i)=>`<button type="button" data-step="${i}"><span>${i+1}</span>${l}</button>`).join('');hero.after(nav);
 const shell=document.createElement('div');shell.className='journey-shell';nav.after(shell);
 const panels=labels.map((l,i)=>{const el=document.createElement('section');el.className='journey-step';el.id='step'+i;el.innerHTML=`<p class="eyebrow">${i<5?'STEP '+(i+1)+' OF 5':'YOUR RESULTS'}</p><h2 tabindex="-1">${['Where does your day start?','How do you get around?','When are you working?','What else needs your time?','What do you need to get done?','Open doesn’t always mean available.'][i]}</h2>`;shell.append(el);return el;});
 const addresses=document.querySelector('.address-entry'),privacy=addresses.nextElementSibling;
 panels[0].append(addresses,privacy);panels[0].insertAdjacentHTML('beforeend','<p class="small">Addresses are optional. You can explore schedules first.</p>');
 const mode=$('mode').parentElement;panels[1].append(mode);
 const choices=document.querySelector('.choices'),work=choices.children[0],service=choices.children[1];panels[2].append(work);panels[4].append(service);choices.remove();
 work.querySelector('h2').remove();service.querySelector('h2').remove();
 const settings=document.querySelector('.settings');settings.open=true;
 const grid=document.querySelector('.settings-grid');const workFields=document.createElement('div');workFields.className='work-fields';panels[2].append(workFields);
 workFields.append($('days').closest('fieldset'),$('start').parentElement,$('end').parentElement);
 panels[1].append($('travel').parentElement);panels[1].insertAdjacentHTML('beforeend','<p class="small">Use an estimated trip length for the office overview. Address-specific routes come next; live travel estimates are not connected.</p>');
 const travelChips=document.createElement('div');travelChips.className='travel-chips';travelChips.innerHTML=['transit','walking','bicycling','driving'].map((v,i)=>`<button type="button" data-mode="${v}">${['Subway / bus','Walking','Cycling','Driving'][i]}</button>`).join('');panels[1].querySelector('h2').after(travelChips);mode.hidden=true;
 panels[4].append($('duration').parentElement,$('wait').parentElement);
 const care=document.querySelector('.care');panels[3].append(care);care.querySelector('label').lastChild.textContent=' School pickup / caregiving (Mon–Fri)';
 panels[3].insertAdjacentHTML('beforeend',`<div class="life-block"><label><input type="checkbox" id="lifeEnabled"> Another commitment</label><input id="lifeLabel" aria-label="Commitment name" placeholder="Class, second job, appointments…" maxlength="60"><div><input id="lifeStart" type="time" value="18:00" aria-label="Commitment starts"> to <input id="lifeEnd" type="time" value="20:00" aria-label="Commitment ends"><select id="lifeDays" aria-label="Commitment days"><option value="weekdays">Weekdays</option><option value="daily">Every day</option><option value="weekends">Weekends</option></select></div></div><div class="life-block"><label><input type="checkbox" id="sleepEnabled"> Protect sleep / recovery time</label><div><input id="sleepStart" type="time" value="07:00" aria-label="Sleep starts"> to <input id="sleepEnd" type="time" value="15:00" aria-label="Sleep ends"><span class="small">Every day</span></div></div><p class="small">Include the time you need to travel to pickup or other commitments. We won’t schedule a trip through these blocks.</p>`);
 // Keep the existing summary target for the model without exposing duplicate controls.
 settings.hidden=true;settings.style.display='none';
 const summary=document.createElement('section');summary.id='accessOverview';panels[5].append(summary,$('routeSetup'),$('result'),document.querySelector('.method'));
 const actions=document.createElement('div');actions.className='journey-actions';actions.innerHTML='<button type="button" id="backStep">← Back</button><button type="button" id="nextStep">Continue →</button>';shell.append(actions);
 function show(n){if(n>step){const invalid=[...panels[step].querySelectorAll('input')].find(i=>!i.checkValidity());if(invalid){invalid.reportValidity();return;}}step=n;panels.forEach((p,i)=>p.hidden=i!==step);nav.querySelectorAll('button').forEach((b,i)=>{b.classList.toggle('active',i===step);if(i===step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});$('backStep').hidden=step===0;$('nextStep').hidden=step===5;$('nextStep').textContent=step===4?'Show my options →':'Continue →';hero.hidden=step===5;panels[step].querySelector('h2').focus({preventScroll:true});}
 $('nextStep').onclick=()=>{const invalid=[...panels[step].querySelectorAll('input')].find(i=>!i.checkValidity());if(invalid){invalid.reportValidity();return;}show(Math.min(5,step+1));};$('backStep').onclick=()=>show(Math.max(0,step-1));nav.onclick=e=>{const b=e.target.closest('[data-step]');if(b)show(+b.dataset.step);};
 function modes(){travelChips.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.mode===$('mode').value);b.setAttribute('aria-pressed',b.dataset.mode===$('mode').value);});}
 travelChips.onclick=e=>{const b=e.target.closest('[data-mode]');if(b){$('mode').value=b.dataset.mode;$('mode').dispatchEvent(new Event('change'));modes();}};
 for(const id of ['start','end','careStart','careEnd','lifeStart','lifeEnd','sleepStart','sleepEnd'])$(id).required=true;
 function constraints(){const E=window.ScheduleEngine,out=[];for(const prefix of ['life','sleep']){if(!$(prefix+'Enabled').checked)continue;const a=E.minutes($(prefix+'Start').value),b=E.minutes($(prefix+'End').value);const days=prefix==='sleep'||$('lifeDays').value==='daily'?[0,1,2,3,4,5,6]:$('lifeDays').value==='weekends'?[5,6]:[0,1,2,3,4];for(const d of days)for(const off of [-10080,0,10080])out.push([d*1440+a+off,d*1440+b+(b<=a?1440:0)+off]);}return out;}
 function overview(s){const E=window.ScheduleEngine,all=window.SCHEDULE_DATA.records;const rows=all.filter(r=>r.channel==='in_person'&&r.service===$('service').value&&($('borough').value==='all'||r.borough===$('borough').value));const results=rows.map(r=>({r,p:E.planVisit(r,s)}));const known=results.filter(x=>!['unknown','closed'].includes(x.p.kind));const fit=known.filter(x=>x.p.kind==='fits').length;const overlap=known.filter(x=>x.p.kind==='overlap').length;const blocked=known.filter(x=>x.p.kind==='blocked').length;const unknown=results.filter(x=>x.p.kind==='unknown').length;const closed=results.filter(x=>x.p.kind==='closed').length;const withoutLife=known.filter(x=>E.planVisit(x.r,{...s,unavailable:[]}).kind==='fits').length;
 $('accessOverview').innerHTML=`<div class="reach-head"><div class="reach-number">${fit}<span> / ${known.length}</span></div><div><h3>office schedules fit your week</h3><p class="small">For this service and borough, with your estimated ${s.travel}-minute trips.</p></div></div><div class="reach-metrics"><div><strong>${overlap}</strong>Overlap work</div><div><strong>${blocked}</strong>Can’t fit around life</div><div><strong>${unknown}</strong>Hours unknown</div></div><p class="small">${withoutLife>fit?`Your protected time removes ${withoutLife-fit} otherwise possible window${withoutLife-fit===1?'':'s'}. `:''}${closed?closed+' listings are closed and excluded. ':''}Possible windows, not confirmed appointments. Counts are service-location records; special-date hours and online options may offer alternatives.</p><details><summary>See every office in this comparison</summary>${results.map(({r,p})=>`<div class="office-fit"><span>${r.name.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}</span><strong>${p.kind==='fits'?'Possible window':p.kind==='overlap'?p.overlap+' min work overlap':p.kind==='blocked'?'Life conflict':p.kind==='closed'?'Listed closed':'Hours unknown'}</strong></div>`).join('')}</details><p class="small">${$('home').value.trim()&&$('work').value.trim()?'Next: check an individual office using your addresses. The overview above uses your estimate, not measured routes.':'Add home and work addresses in Your places to check an individual trip.'}</p>`;
 }
 modes();show(0);return {constraints,overview};
})();
